import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import test from "node:test";

import { CONTRACT_PRECISION } from "@dfpunk/constants";
import { estimateEnergyArriving } from "@dfpunk/gamelogic";

import { decayedPopArriving } from "../src/Session/TxExecutor/MoveSimulation.ts";

// Generated by contracts/scripts/check/move-decay-vectors.ts; the Noir test
// move_decay::matches_client_vectors checks the contract against the same rows.
const VECTORS = path.resolve(
  import.meta.dirname,
  "../../contracts/tests/high_level_planet/src/move_decay_vectors.nr"
);

type Row = {
  pop: bigint;
  cap: bigint;
  range: bigint;
  dist: bigint;
  contract: bigint;
};

function readRows(): Row[] {
  const source = fs.readFileSync(VECTORS, "utf-8");
  const rows = [...source.matchAll(/\((\d+), (\d+), (\d+), (\d+), (\d+)\)/g)];
  const declared = Number(source.match(/; (\d+)\] =/)?.[1]);
  assert.equal(rows.length, declared, "failed to parse every table row");
  return rows.map(([, pop, cap, range, dist, contract]) => ({
    pop: BigInt(pop),
    cap: BigInt(cap),
    range: BigInt(range),
    dist: BigInt(dist),
    contract: BigInt(contract),
  }));
}

const rows = readRows();

test("decayedPopArriving matches every row of the contract table", () => {
  for (const r of rows) {
    assert.equal(
      decayedPopArriving(r.pop, r.cap, r.range, r.dist),
      r.contract,
      `pop=${r.pop} cap=${r.cap} range=${r.range} dist=${r.dist}`
    );
  }
});

// The move pane shows estimateEnergyArriving (floats, UI units). The contract
// floors to whole contract units, so the UI may show up to one unit more, never
// a full unit where the contract delivers nothing.
test("UI arrival estimate stays within one contract unit of the contract", () => {
  for (const r of rows) {
    const ui = estimateEnergyArriving(
      Number(r.pop) / CONTRACT_PRECISION,
      Number(r.cap) / CONTRACT_PRECISION,
      Number(r.range),
      Number(r.dist) / 100
    );
    const uiUnits = ui * CONTRACT_PRECISION;
    const label = `pop=${r.pop} cap=${r.cap} range=${r.range} dist=${r.dist}: ui=${uiUnits} contract=${r.contract}`;
    const tolerance = 1 + Number(r.pop) * 1e-12;
    assert.ok(
      uiUnits >= Number(r.contract) - tolerance,
      `UI below contract, ${label}`
    );
    assert.ok(
      uiUnits < Number(r.contract) + tolerance,
      `UI above contract, ${label}`
    );
  }
});

test("level 8 rank 3: sends below 1% of the cap still reach a neighbour", () => {
  const cap = 1_209_600_000n;
  const range = 6_306n;
  for (const share of [1n, 10n, 99n]) {
    const pop = (cap * share) / 10_000n;
    const arriving = decayedPopArriving(pop, cap, range, 100n);
    assert.ok(
      arriving > 0n && arriving <= pop,
      `share ${share} bp: ${arriving}`
    );
  }
});
